CREATE OR REPLACE FUNCTION access_roles() RETURNS TABLE (role_key text, role_name text, role_description text, is_system boolean, copied_from text)
LANGUAGE sql IMMUTABLE AS $$
  SELECT * FROM (VALUES
    ('OWNER', 'Owner', 'Owns the school. Full access to everything.', true, NULL::text),
    ('HEAD', 'Head', 'The head of the school. Oversees teaching, staff and finance.', true, NULL::text),
    ('DEPUTY_HEAD', 'Deputy Head', 'Supports the head and runs day-to-day discipline and timetabling.', true, NULL::text),
    ('ADMINISTRATOR', 'Administrator', 'Runs the system for the school: users, settings, calendar and records.', true, NULL::text),
    ('BURSAR', 'Bursar', 'Manages fees, payments, expenses and the school accounts.', true, NULL::text),
    ('ACCOUNTS_CLERK', 'Accounts Clerk', 'Records payments and keeps the daily accounts under the bursar.', true, NULL::text),
    ('HR_OFFICER', 'HR Officer', 'Looks after staff records, leave and payroll.', true, NULL::text),
    ('HOD', 'Head of Department', 'Leads a subject department and its teachers.', true, NULL::text),
    ('TEACHER', 'Teacher', 'Teaches classes and enters marks for their subjects.', true, NULL::text),
    ('CLASS_TEACHER', 'Class Teacher', 'Looks after one class: register, remarks and report cards.', true, NULL::text),
    ('EXAMS_OFFICER', 'Exams Officer', 'Runs internal and ZIMSEC examinations and their results.', true, NULL::text),
    ('LIBRARIAN', 'Librarian', 'Runs the library: books, borrowing and fines.', true, NULL::text),
    ('BOARDING_MASTER', 'Boarding Master', 'Looks after the boarding hostels and the boarders.', true, NULL::text),
    ('MATRON', 'Matron', 'Looks after the sick bay and the medical notes of the boarders in her hostel.', true, NULL::text),
    ('STOREKEEPER', 'Storekeeper', 'Keeps one store: receives, issues and counts stock.', false, 'BURSAR'),
    ('TRANSPORT_OFFICER', 'Transport Officer', 'Runs routes, vehicles, trips and learner transport.', false, 'BURSAR'),
    ('TUCKSHOP_ATTENDANT', 'Tuck Shop Attendant', 'Sells at the tuck shop.', false, 'BOARDING_MASTER'),
    ('NURSE', 'Nurse', 'The Matron''s sick bay and medical access for the whole school.', false, 'MATRON')
  ) AS v(role_key, role_name, role_description, is_system, copied_from)
$$;

CREATE OR REPLACE FUNCTION access_grants() RETURNS TABLE (role_key text, permission_key text, scope "AccessScope")
LANGUAGE sql IMMUTABLE AS $$
  SELECT v.r, v.k, v.s::"AccessScope" FROM (VALUES
    ('OWNER', 'academics.analytics.view', 'SCHOOL'),
    ('OWNER', 'academics.assignments.view', 'SCHOOL'),
    ('OWNER', 'academics.attendance.view', 'SCHOOL'),
    ('OWNER', 'academics.classes.view', 'SCHOOL'),
    ('OWNER', 'academics.schemes.view', 'SCHOOL'),
    ('OWNER', 'academics.subjects.view', 'SCHOOL'),
    ('OWNER', 'academics.timetable.view', 'SCHOOL'),
